<?php
$page_title='Add Course'; require_once __DIR__.'/../../config/database.php'; require_once __DIR__.'/../../config/session.php'; require_once __DIR__.'/../../config/functions.php'; require_once __DIR__.'/../../config/auth.php'; requireAdmin();
$mentors=$pdo->query("SELECT id,full_name FROM users WHERE role='mentor' AND is_active=1 ORDER BY full_name")->fetchAll(); $fields=$pdo->query('SELECT id,name FROM academic_fields WHERE is_active=1 ORDER BY name')->fetchAll(); $errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){ $title=trim($_POST['title']??''); $mentor=(int)($_POST['mentor_id']??0); $field=(int)($_POST['field_id']??0); $description=trim($_POST['description']??''); $level=$_POST['level']??'beginner'; $price=(float)($_POST['price']??0); $duration=(int)($_POST['duration']??0); $status=$_POST['status']??'draft'; if($title==='')$errors[]='Course title is required.'; if(!$mentor)$errors[]='Select a mentor.'; if(!$errors){$stmt=$pdo->prepare('INSERT INTO courses (mentor_id,field_id,title,slug,description,price,level,duration,status,featured) VALUES (?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$mentor,$field?:null,$title,createSlug($title),$description,$price,$level,$duration,$status,isset($_POST['featured'])?1:0]);header('Location: index.php');exit;}}
?>
<?php include __DIR__.'/../includes/header.php'; ?><div class="admin-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><main class="admin-main"><div class="admin-topbar"><div><h1 class="admin-title">Add course</h1><p class="admin-subtitle">Create a catalogue entry and assign ownership.</p></div><a class="btn btn-outline-secondary" href="index.php">Back</a></div><div class="admin-card"><form method="POST"><div class="admin-form-grid"><div class="full"><label>Title</label><input name="title" required value="<?php echo htmlspecialchars($_POST['title']??''); ?>"></div><div><label>Mentor</label><select name="mentor_id" required><option value="">Select mentor</option><?php foreach($mentors as $mentor): ?><option value="<?php echo $mentor['id']; ?>"><?php echo htmlspecialchars($mentor['full_name']); ?></option><?php endforeach; ?></select></div><div><label>Academic field</label><select name="field_id"><option value="">General</option><?php foreach($fields as $field): ?><option value="<?php echo $field['id']; ?>"><?php echo htmlspecialchars($field['name']); ?></option><?php endforeach; ?></select></div><div><label>Level</label><select name="level"><option>beginner</option><option>intermediate</option><option>advanced</option></select></div><div><label>Status</label><select name="status"><option value="draft">Draft</option><option value="pending">Pending</option><option value="active">Active</option><option value="inactive">Inactive</option></select></div><div><label>Price</label><input type="number" step="0.01" min="0" name="price" value="0"></div><div><label>Duration (hours)</label><input type="number" min="0" name="duration" value="0"></div><div class="full"><label>Description</label><textarea name="description"><?php echo htmlspecialchars($_POST['description']??''); ?></textarea></div><div><label><input type="checkbox" name="featured"> Featured course</label></div></div><?php foreach($errors as $error): ?><div class="alert alert-danger mt-3"><?php echo htmlspecialchars($error); ?></div><?php endforeach; ?><button class="btn btn-primary mt-3"><i class="fas fa-save"></i> Create course</button></form></div></main></div><?php include __DIR__.'/../includes/footer.php'; ?>
